    Height: 16\n  - name: imgE40\n    type: Image\n    properties:\n      Picture: enemy.png\n      Left: 0\n      Top: -100\n      Width: 24\n      Height: 16\n  - name: imgB1\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgB2\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgB3\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgB4\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgB5\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgB6\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgB7\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgB8\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgB9\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgB10\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgF1\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgF2\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n      Width: 4\n      Height: 10\n  - name: imgF3\n    type: Image\n    properties:\n      Picture: bullet.png\n      Left: 0\n      Top: -100\n