    "Form1.gbas": "' Benchmark 5 (STAGE2_PLAN §7): a game like Galaga. 40 enemies, up to\n' 10 of the player's bullets and 10 of the enemies', and the player's\n' ship move every round; every bullet is checked against every enemy and\n' the ship. With no Timer yet, DoEvents ends each round, as a 16 ms Timer\n' (60 a second) would. Gone things move off the form (y = -100): an\n' Image has no Visible yet.\nDim ex(39) As Integer\nDim ey(39) As Integer\nDim alive(39) As Boolean\nDim bx(9) As Integer\nDim by(9) As Integer\nDim fx(9) As Integer\nDim fy(9) As Integer\nDim shipX As Integer\nDim shipDx As Integer\nDim sway As Integer\nDim swayDx As Integer\nDim score As Integer\nDim hits As Integer\n\nSub Form_Load()\n    Dim i As Integer\n    For i = 0 To 39\n        ex(i) = 40 + (i Mod 10) * 40\n        ey(i) = 60 + (i \\ 10) * 32\n        alive(i) = True\n    Next\n    For i = 0 To 9\n        by(i) = -100\n        fy(i) = -100\n    Next\n    shipX = 224\n    shipDx = 3\n    swayDx = 1\nEnd Sub\n\nSub btnStart_Click()\n    Debug.Print(\"bench:start\")\n    Dim r As Integer\n    Dim i As Integer\n    Dim j As Integer\n    For r = 1 To 600\n        ' The formation sways; the ship goes from side to side.\n        sway = sway + swayDx\n        If sway > 30 Or sway < -30 Then\n            swayDx = -swayDx\n        End If\n        For i = 0 To 39\n            If alive(i) Then\n                ex(i) = 40 + (i Mod 10) * 40 + sway\n            Else\n                ey(i) = -100\n            End If\n        Next\n        shipX = shipX + shipDx\n        If shipX < 0 Or shipX > 448 Then\n            shipDx = -shipDx\n        End If\n        ' The player fires every 6 rounds, an enemy every 8.\n        If r Mod 6 = 0 Then\n            For i = 0 To 9\n                If by(i) < 0 Then\n                    bx(i) = shipX + 14\n                    by(i) = 580\n                    Exit For\n                End If\n            Next\n        End If\n        If r Mod 8 = 0 Then\n            j = r Mod 40\n            If alive(j) Then\n                For i = 0 To 9\n                    If fy(i) < 0 Then\n                        fx(i) = ex(j) + 10\n                        fy(i) = ey(j) + 16\n                        Exit For\n                    End If\n                Next\n            End If\n        End If\n        ' Bullets move; each is checked against every enemy, or the ship.\n        For i = 0 To 9\n            If by(i) >= 0 Then\n                by(i) = by(i) - 8\n                For j = 0 To 39\n                    If alive(j) Then\n                        If bx(i) >= ex(j) And bx(i) < ex(j) + 24 And by(i) >= ey(j) And by(i) < ey(j) + 16 Then\n                            alive(j) = False\n                            by(i) = -100\n                            score = score + 10\n                        End If\n                    End If\n                Next\n            End If\n            If fy(i) >= 0 Then\n                fy(i) = fy(i) + 6\n                If fy(i) > 640 Then\n                    fy(i) = -100\n                End If\n                If fx(i) >= shipX And fx(i) < shipX + 32 And fy(i) >= 590 And fy(i) < 614 Then\n                    hits = hits + 1\n                    fy(i) = -100\n                End If\n            End If\n        Next\n        imgE1.Left = ex(0)\n        imgE1.Top = ey(0)\n        imgE2.Left = ex(1)\n        imgE2.Top = ey(1)\n        imgE3.Left = ex(2)\n        imgE3.Top = ey(2)\n        imgE4.Left = ex(3)\n        imgE4.Top = ey(3)\n        imgE5.Left = ex(4)\n        imgE5.Top = ey(4)\n        imgE6.Left = ex(5)\n        imgE6.Top = ey(5)\n        imgE7.Left = ex(6)\n        imgE7.Top = ey(6)\n        imgE8.Left = ex(7)\n        imgE8.Top = ey(7)\n        imgE9.Left = ex(8)\n        imgE9.Top = ey(8)\n        imgE10.Left = ex(9)\n        imgE10.Top = ey(9)\n        imgE11.Left = ex(10)\n        imgE11.Top = ey(10)\n        imgE12.Left = ex(11)\n        imgE12.Top = ey(11)\n        imgE13.Left = ex(12)\n        imgE13.Top = ey(12)\n        imgE14.Left = ex(13)\n        imgE14.Top = ey(13)\n        imgE15.Left = ex(14)\n        imgE15.Top = ey(14)\n        imgE16.Left = ex(15)\n        imgE16.Top = ey(15)\n        imgE17.Left = ex(16)\n        imgE17.Top = ey(16)\n        imgE18.Left = ex(17)\n        imgE18.Top = ey(17)\n        imgE19.Left = ex(18)\n        imgE19.Top = ey(18)\n        imgE20.Left = ex(19)\n        imgE20.Top = ey(19)\n        imgE21.Left = ex(20)\n        imgE21.Top = ey(20)\n        imgE22.Left = ex(21)\n        imgE22.Top = ey(21)\n        imgE23.Left = ex(22)\n        imgE23.Top = ey(22)\n        imgE24.Left = ex(23)\n        imgE24.Top = ey(23)\n        imgE25.Left = ex(24)\n        imgE25.Top = ey(24)\n        imgE26.Left = ex(25)\n        imgE26.Top = ey(25)\n        imgE27.Left = ex(26)\n        imgE27.Top = ey(26)\n        imgE28.Left = ex(27)\n        imgE28.Top = ey(27)\n        imgE29.Left = ex(28)\n        imgE29.Top = ey(28)\n        imgE30.Left = ex(29)\n        imgE30.Top = ey(29)\n        imgE31.Left = ex(30)\n        imgE31.Top = ey(30)\n        imgE32.Left = ex(31)\n        imgE32.Top = ey(31)\n        imgE33.Left = ex(32)\n        imgE33.Top = ey(32)\n        imgE34.Left = ex(33)\n        imgE34.Top = ey(33)\n        imgE35.Left = ex(34)\n        imgE35.Top = ey(34)\n        imgE36.Left = ex(35)\n        imgE36.Top = ey(35)\n        imgE37.Left = ex(36)\n        imgE37.Top = ey(36)\n        imgE38.Left = ex(37)\n        imgE38.Top = ey(37)\n        imgE39.Left = ex(38)\n        imgE39.Top = ey(38)\n        imgE40.Left = ex(39)\n        imgE40.Top = ey(39)\n        imgB1.Left = bx(0)\n        imgB1.Top = by(0)\n        imgB2.Left = bx(1)\n        imgB2.Top = by(1)\n        imgB3.Left = bx(2)\n        imgB3.Top = by(2)\n        imgB4.Left = bx(3)\n        imgB4.Top = by(3)\n        imgB5.Left = bx(4)\n        imgB5.Top = by(4)\n        imgB6.Left = bx(5)\n        imgB6.Top = by(5)\n        imgB7.Left = bx(6)\n        imgB7.Top = by(6)\n        imgB8.Left = bx(7)\n        imgB8.Top = by(7)\n        imgB9.Left = bx(8)\n        imgB9.Top = by(8)\n        imgB10.Left = bx(9)\n        imgB10.Top = by(9)\n        imgF1.Left = fx(0)\n        imgF1.Top = fy(0)\n        imgF2.Left = fx(1)\n        imgF2.Top = fy(1)\n        imgF3.Left = fx(2)\n        imgF3.Top = fy(2)\n        imgF4.Left = fx(3)\n        imgF4.Top = fy(3)\n        imgF5.Left = fx(4)\n        imgF5.Top = fy(4)\n        imgF6.Left = fx(5)\n        imgF6.Top = fy(5)\n        imgF7.Left = fx(6)\n        imgF7.Top = fy(6)\n        imgF8.Left = fx(7)\n        imgF8.Top = fy(7)\n        imgF9.Left = fx(8)\n        imgF9.Top = fy(8)\n        imgF10.Left = fx(9)\n        imgF10.Top = fy(9)\n        imgShip.Left = shipX\n        imgShip.Top = 590\n        lblScore.Caption = \"Score: \" & score & \"  Hits: \" & hits\n        DoEvents\n    Next\n    Debug.Print(\"bench:end \" & score & \" \" & hits)\nEnd Sub\n",
